# Generated by manage.py generate_test_cases.
"""Host-only session closure and idempotent media cleanup."""

from django.http import HttpResponse

from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.conferencing.fixtures import CallFixtures


class TestEndComponent(CallFixtures, BloomerpComponentTestCase):
    view_name = "components_conferencing_end"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover host authority, nonhost denial and safe repeated closure."""
        return [
            RequestScenario(
                name="Host ends call",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_session,
                expected=ExpectedResult(response_validators=self.closed),
            ),
            RequestScenario(
                name="Nonhost administrator cannot end for everyone",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_session,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Repeated end remains successful",
                method="POST",
                user=self.normal_user,
                prepare=self.ended_session,
                expected=ExpectedResult(response_validators=self.closed),
            ),
            RequestScenario(
                name="Media cleanup failure retains local closure",
                method="POST",
                user=self.normal_user,
                prepare=self.failed_cleanup,
                expected=ExpectedResult(
                    status_code=503, response_validators=self.closed
                ),
            ),
            RequestScenario(
                name="GET cannot end calls",
                user=self.normal_user,
                prepare=self.prepare_session,
                expected=ExpectedResult(status_code=405),
            ),
        ]

    def closed(self, response: HttpResponse) -> bool:
        """Ensure no new tokens can be issued after termination, even if cleanup fails."""
        self.session.refresh_from_db()
        return self.session.status == "cancelled" and self.session.ended_at is not None

    def failed_cleanup(self, scenario: RequestScenario) -> None:
        """Simulate transport failure after the call is closed durably."""
        self.prepare_session(scenario)
        self.delete_room.side_effect = TimeoutError
